{
  "packet_id": "H6-T01-1",
  "claim_id": "C018",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C018.component",
    "value": "Persistent delay at a stage supports choosing a trial change directed at that stage.",
    "scope": "The proposed day-14 choice remains conditional on findings and feasibility with existing equipment and staffing; it is not a report that a stage has been established.",
    "provenance": {
      "refs": [
        {"source_id": "P011", "role": "CONTEXT"},
        {"source_id": "P012", "role": "SUPPORT"},
        {"source_id": "P013", "role": "SUPPORT"},
        {"source_id": "P021", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P021 supplies the targeting relation, P012 the day-14 selection, P013 its conditions, and P011 the preceding stage-selection context."
    }
  },
  "signal_basis": {
    "component_id": "C018.signal_basis",
    "value": "Stage-specific delay recurs on multiple booking days in each investigation week, with the same stage carrying the greatest documented delay burden in both weeks.",
    "scope": "The prospective two-week sequence uses daily review and weekly summaries, comparing comparable equipment and crew groups before pooling. The rule requires adequate bookings and a ranking that missing records could not reverse. This is an assumed observation for this judgment, not an already reported finding; the persistence rule supports practical selection without statistical proof or causal identification.",
    "provenance": {
      "refs": [
        {"source_id": "P009", "role": "SUPPORT"},
        {"source_id": "P010", "role": "SUPPORT"},
        {"source_id": "P011", "role": "SUPPORT"},
        {"source_id": "P014", "role": "SUPPORT"},
        {"source_id": "P018", "role": "SUPPORT"},
        {"source_id": "P025", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P011 defines the recurrence and burden signal. P009–P010 supply the review and comparison requirements; P014 supplies the missingness and sparsity restrictions. P018 establishes that findings are prospective, and P025 bounds the rule's inferential force."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C018.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This component is inapplicable because the bounded claim is supported without an additional unresolved empirical relation."
    }
  },
  "rationale": "Assuming the specified signal occurs and prerequisites are satisfied, recurrent concentration of documented delay at one stage provides a reason to direct a feasible trial there. The claim concerns trial selection, so it does not require proof that the stage causes all late starts or that the chosen change will succeed.",
  "uncertainty": "The short observation period cannot establish long-term persistence, causal responsibility, or intervention effectiveness. These limits are compatible with the claim's practical, provisional trial-selection scope.",
  "anomalies": []
}
